# Status lifecycles shared by type families. Unlisted types use the generic lifecycle.
WORKFLOWS = {
    "generic": {
        "draft": {"submit": "submitted", "cancel": "cancelled"},
        "submitted": {"start": "in_progress", "approve": "approved", "reject": "rejected", "cancel": "cancelled"},
        "in_progress": {"complete": "completed", "hold": "on_hold", "cancel": "cancelled"},
        "on_hold": {"resume": "in_progress", "cancel": "cancelled"},
        "approved": {"complete": "completed", "reopen": "in_progress"},
        "completed": {"amend": "amended"},
        "amended": {"complete": "completed"},
    },
    "medication_dose": {
        "due": {"administer": "given", "withhold": "withheld", "refuse": "refused", "omit": "omitted", "mark_late": "late"},
        "late": {"administer": "given", "withhold": "withheld", "omit": "omitted"},
    },
    "critical_imaging_alert": {
        "draft": {"notify": "notified"},
        "notified": {"acknowledge": "acknowledged", "escalate": "escalated"},
        "escalated": {"acknowledge": "acknowledged", "escalate": "escalated"},
    },
    "security_alert": {
        "open": {"triage": "triaged", "contain": "contained", "dismiss": "dismissed"},
        "triaged": {"contain": "contained", "resolve": "resolved"},
        "contained": {"resolve": "resolved", "reopen": "open"},
        "resolved": {"reopen": "open"},
    },
}


def schema_for(record_type):
    return RECORD_SCHEMAS.get(record_type)


def validate_record(domain, record_type, payload):
    schema = schema_for(record_type)
    if not schema:
        raise ValidationError({"record_type": f"Unsupported enterprise record type: {record_type}."})
    if schema["domain"] != domain:
        raise ValidationError({"domain": f"{record_type} belongs to the {schema['domain']} domain."})
    if not isinstance(payload, dict):
        raise ValidationError({"payload": "Payload must be an object."})
    missing = [name for name, spec in schema["fields"].items() if spec.get("required") and payload.get(name) in (None, "", [])]
    if missing:
        raise ValidationError({"payload": [f"{name}: This field is required." for name in missing]})
    unknown = set(payload) - set(schema["fields"])
    if unknown:
        raise ValidationError({"payload": [f"{name}: Unknown field for this record type." for name in sorted(unknown)]})
    for name, value in payload.items():
        kind = schema["fields"][name].get("kind")
        if value in (None, ""):
            continue
        if kind == "number" and not isinstance(value, (int, float)):
            raise ValidationError({"payload": [f"{name}: Must be numeric."]})
        if kind == "boolean" and not isinstance(value, bool):
            raise ValidationError({"payload": [f"{name}: Must be true or false."]})
        if kind == "list" and not isinstance(value, list):
            raise ValidationError({"payload": [f"{name}: Must be a list."]})
        if kind == "json" and not isinstance(value, (dict, list)):
            raise ValidationError({"payload": [f"{name}: Must be an object or list."]})
        options = schema["fields"][name].get("options")
        if options and value not in options:
            raise ValidationError({"payload": [f"{name}: Must be one of: {', '.join(options)}."]})


def transition_for(record_type, current_status, action):
    workflow = WORKFLOWS.get(record_type, WORKFLOWS["generic"])
    return workflow.get(current_status, {}).get(action)


def public_schema_catalog():
    return {
        key: {
            "record_type": key,
            "domain": value["domain"],
            "label": value["label"],
            "roles": value["roles"],
            "fields": value["fields"],
            "workflow": WORKFLOWS.get(key, WORKFLOWS["generic"]),
        }
        for key, value in RECORD_SCHEMAS.items()
    }
